	(1, 1, 'Um comentarista do WordPress', 'wapuu@wordpress.example', 'https://br.wordpress.org/', '', '2026-07-02 12:04:29', '2026-07-02 15:04:29', 'Oi, isto é um comentário.\nPara iniciar a moderar, editar e excluir comentários, visite a tela Comentários no painel.\nOs avatares dos comentaristas vêm do <a href="https://br.gravatar.com/">Gravatar</a>.', 0, '1', '', 'comment', 0, 0);
