	(7, 1, '2026-07-02 13:36:51', '2026-07-02 16:36:51', '<!-- wp:template-part {"slug":"header","theme":"twentytwentyfive"} /-->\n\n<!-- wp:group {"tagName":"main","style":{"spacing":{"margin":{"top":"var:preset|spacing|60"}}},"layout":{"type":"constrained"}} -->\n<main class="wp-block-group" style="margin-top:var(--wp--preset--spacing--60)"><!-- wp:heading {"level":1,"metadata":{"patternName":"twentytwentyfive/hidden-blog-heading","name":"Hidden blog heading","description":"Hidden heading for the home page and index template."},"style":{"typography":{"textAlign":"left"}}} -->\n<h1 class="wp-block-heading has-text-align-left"></h1>\n<!-- /wp:heading -->\n\n<!-- wp:query {"queryId":0,"query":{"perPage":10,"pages":0,"offset":0,"postType":"post","order":"desc","orderBy":"date","author":"","search":"","exclude":[],"sticky":"","inherit":true,"taxQuery":null,"parents":[]},"metadata":{"patternName":"twentytwentyfive/template-query-loop","name":"List of posts, 1 column","description":"A list of posts, 1 column, with featured image and post date.","categories":["query"]},"align":"full","layout":{"type":"default"}} -->\n<div class="wp-block-query alignfull"><!-- wp:post-template {"align":"full","layout":{"type":"default"}} -->\n<!-- wp:group {"align":"full","style":{"spacing":{"padding":{"top":"var:preset|spacing|60","bottom":"var:preset|spacing|60"}}},"layout":{"type":"constrained"}} -->\n<div class="wp-block-group alignfull" style="padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)"><!-- wp:post-featured-image {"isLink":true,"aspectRatio":"3/2"} /-->\n\n<!-- wp:post-title {"isLink":true,"fontSize":"x-large"} /-->\n\n<!-- wp:post-content {"align":"full","fontSize":"medium","layout":{"type":"constrained"}} /-->\n\n<!-- wp:post-date {"isLink":true,"metadata":{"bindings":{"datetime":{"source":"core/post-data","args":{"field":"date"}}}},"style":{"spacing":{"margin":{"top":"var:preset|spacing|40"}}},"fontSize":"small"} /--></div>\n<!-- /wp:group -->\n<!-- /wp:post-template -->\n\n<!-- wp:group {"style":{"spacing":{"padding":{"top":"var:preset|spacing|60","bottom":"var:preset|spacing|60"}}},"layout":{"type":"constrained"}} -->\n<div class="wp-block-group" style="padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)"><!-- wp:query-no-results -->\n<!-- wp:paragraph -->\n<p>Sorry, but nothing was found. Please try a search with different keywords.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:query-no-results --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {"align":"wide","layout":{"type":"constrained"}} -->\n<div class="wp-block-group alignwide"><!-- wp:query-pagination {"paginationArrow":"arrow","align":"wide","layout":{"type":"flex","justifyContent":"space-between"}} -->\n<!-- wp:query-pagination-previous /-->\n\n<!-- wp:query-pagination-numbers /-->\n\n<!-- wp:query-pagination-next /-->\n<!-- /wp:query-pagination --></div>\n<!-- /wp:group --></div>\n<!-- /wp:query --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {"slug":"footer","theme":"twentytwentyfive"} /-->', 'Página inicial do blog', 'Exibe os posts mais recentes como página inicial do site ou uma página personalizada definida nas configurações de leitura. Se existir, o modelo da página principal substitui esse modelo quando os posts são exibidos na página principal.', 'publish', 'closed', 'closed', '', 'home', '', '', '2026-07-02 13:36:51', '2026-07-02 16:36:51', '', 0, 'https://versaoltda.test/?p=7', 0, 'wp_template', '', 0),
